import{_ as a,c as t,o,a2 as c}from"./chunks/framework.Cqt7uvsz.js";const p=JSON.parse('{"title":"Vue computed 和 watch 区别","description":"","frontmatter":{},"headers":[],"relativePath":"interview/前端基础知识/09-vue-computed-watch-区别.md","filePath":"interview/前端基础知识/09-vue-computed-watch-区别.md","lastUpdated":1766579221000}'),d={name:"interview/前端基础知识/09-vue-computed-watch-区别.md"};function i(l,e,u,r,h,n){return o(),t("div",null,e[0]||(e[0]=[c('<h1 id="vue-computed-和-watch-区别" tabindex="-1">Vue computed 和 watch 区别 <a class="header-anchor" href="#vue-computed-和-watch-区别" aria-label="Permalink to &quot;Vue computed 和 watch 区别&quot;">​</a></h1><h2 id="题目" tabindex="-1">题目 <a class="header-anchor" href="#题目" aria-label="Permalink to &quot;题目&quot;">​</a></h2><p>Vue computed 和 watch 区别</p><h2 id="两者设计用途不同" tabindex="-1">两者设计用途不同 <a class="header-anchor" href="#两者设计用途不同" aria-label="Permalink to &quot;两者设计用途不同&quot;">​</a></h2><ul><li>computed 用于产出二次处理之后的数据，如对于一个列表进行 filter 处理</li><li>watch 用于监听数据变化（如 v-model 时，数据可能被动改变，需要监听才能拿到）</li></ul><h2 id="computed-有缓存" tabindex="-1">computed 有缓存 <a class="header-anchor" href="#computed-有缓存" aria-label="Permalink to &quot;computed 有缓存&quot;">​</a></h2><ul><li>computed 有缓存，data 不变则缓存不失效</li><li>methods 无缓存，实时计算</li></ul><h2 id="答案" tabindex="-1">答案 <a class="header-anchor" href="#答案" aria-label="Permalink to &quot;答案&quot;">​</a></h2><ul><li>computed 就已有数据产出新数据，有缓存</li><li>watch 监听已有数据</li></ul><hr><p>代码参考 WatchAndComputed.vue</p>',11)]))}const s=a(d,[["render",i]]);export{p as __pageData,s as default};
